  var LOUNGE_SEATS = [{ prop: 'lobbyBenchL', lx: -0.38 }, { prop: 'lobbyBenchL', lx: 0.38 }, { prop: 'lobbyBenchR', lx: -0.38 }, { prop: 'lobbyBenchR', lx: 0.38 }];
