    P.lLeg.rotation.x = lerp(P.lLeg.rotation.x, -1.25 * k, s); P.rLeg.rotation.x = lerp(P.rLeg.rotation.x, -1.2 * k, s);
    lk.rotation.x = lerp(lk.rotation.x, 1.0 * k, s); rk.rotation.x = lerp(rk.rotation.x, 0.95 * k, s);
