    if ((S.coffeeStock.beans || 0) <= 0) { toast('Out of beans', 'bad'); return; }
    if ((S.pocket || 0) < 2) { sfx('bad'); toast('A cup is $2 from your pocket, and your pocket is short', 'bad'); return; }
